import plistlib, subprocess
base = "f783f19c8a01fbe8d0ed70d851df7ed14598c051"
for rel in ["intelligence/dream/com.financeworkspace.daily-full-review-sync.plist",
            "intelligence/dream/com.financeworkspace.daily-full-review-finalize.plist"]:
    cur = plistlib.load(open(rel, "rb"))
    old = plistlib.loads(subprocess.run(["git","show",f"{base}:{rel}"],capture_output=True,check=True).stdout)
    # scheduling-relevant keys
    sched = {k: cur.get(k) for k in ("StartCalendarInterval","StartInterval","KeepAlive","WatchPaths","StartOnMount","RunAtLoad","LaunchOnlyOnce") if k in cur}
    print(rel.split("-")[-1], "scheduling keys:", sched)
    keys = set(old) | set(cur)
    for k in sorted(keys):
        if old.get(k) != cur.get(k):
            if k == "EnvironmentVariables":
                eold, ecur = old[k], cur[k]
                for ek in sorted(set(eold)|set(ecur)):
                    if eold.get(ek) != ecur.get(ek):
                        print(f"  env.{ek}: {eold.get(ek)!r} -> {ecur.get(ek)!r}")
            else:
                print(f"  {k}: {old.get(k)!r} -> {cur.get(k)!r}")
EOF

